WHERE full_adm_path IS NOT NULL OR full_mun_path IS NOT NULL;

UPDATE gar.houses SET
  full_adm_path_tsv = to_tsvector('russian', COALESCE(full_adm_path, '')),
  full_mun_path_tsv = to_tsvector('russian', COALESCE(full_mun_path, ''))
